<template>
  <div class="max-w-4xl mx-auto p-6">
    <h1 class="text-3xl font-semibold mb-6 text-center text-gray-800">YouTube Search</h1>
    <input
      v-model="query"
      type="text"
      class="w-4/5 p-3 border border-gray-300 rounded-lg text-lg"
      placeholder="Search for YouTube videos"
    />
    <button
      @click="searchVideos"
      class="ml-4 p-3 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
    >
      Search
    </button>

    <div v-if="loading" class="text-center text-gray-500">Loading...</div>

    <div v-if="videos.length" class="space-y-6">
      <h2 class="text-2xl font-semibold text-gray-800">Search Results</h2>
      <ul class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        <li v-for="video in videos" :key="video.id" class="bg-white rounded-lg shadow-md overflow-hidden">
          <div @click="goToVideoPage(video.id)" class="cursor-pointer">
            <img
              :src="video.thumbnail"
              alt="Thumbnail"
              class="w-full h-40 object-cover"
            />
            <div class="p-4">
              <p class="text-lg font-semibold text-gray-700">{{ video.title }}</p>
            </div>
          </div>
        </li>
      </ul>
    </div>

    <div v-if="error" class="text-center text-red-600 mt-6">
      <p>{{ error }}</p>
    </div>
  </div>
</template>

<script>
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import axios from 'axios';

export default {
  setup() {
    const query = ref('');
    const videos = ref([]);
    const loading = ref(false);
    const error = ref(null);
    const router = useRouter(); // Access Vue Router

    const searchVideos = async () => {
      if (!query.value) return;

      loading.value = true;
      error.value = null;
      try {
        const response = await axios.get('https://localhost:3000/proxy-video', {
          params: { url: query.value },
        });
        videos.value = response.data.items;
      } catch (err) {
        error.value = 'Failed to fetch videos. Please try again later.';
      } finally {
        loading.value = false;
      }
    };

    const goToVideoPage = (id) => {
      console.log('Navigating to video page with ID:', id); // Log the video ID for debugging
      
      router.push({ name: 'video', params: { id } }); // Navigate to video page
    };

    return {
      query,
      videos,
      loading,
      error,
      searchVideos,
      goToVideoPage, // Expose goToVideoPage method to the template
    };
  },
};
</script>
