import { createRouter, createWebHistory } from 'vue-router';
import SearchComponent from '../components/SearchComponent.vue';
import VideoPage from '../components/VideoPage.vue'; // Make sure this component exists

const routes = [
  {
    path: '/',
    name: 'home',
    component: SearchComponent,
  },
  {
    path: '/video/:id',  // This is the route for the individual video page
    name: 'video',
    component: VideoPage,
    props: true,  // This allows you to pass `id` as a prop to the component
  },
];

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes,
});

export default router;
