<template>
  <div class="max-w-4xl mx-auto p-6">
    <h1 class="text-3xl font-semibold mb-6 text-center text-gray-800">Now Playing</h1>
    <div v-if="video">
      <h2 class="text-2xl font-semibold text-gray-800">{{ video.title }}</h2>
      <video controls class="w-full mt-4">
        <source :src="`http://localhost:3000/stream-video?videoId=${video.id}`" type="video/mp4" />
        Your browser does not support the video tag.
      </video>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  props: ['id'], // Video ID is passed as a prop
  data() {
    return {
      video: null,
    };
  },
  mounted() {
    this.fetchVideoDetails();
  },
  methods: {
    async fetchVideoDetails() {
      try {
        const response = await axios.get('https://localhost:3000/proxy-video', {
          params: { url: this.id }, // Use the `id` from route params
        });
        this.video = response.data.items.find((video) => video.id === this.id);
      } catch (err) {
        console.error('Error fetching video:', err);
      }
    },
  },
};
</script>
